-- Add the HumanHelpRequest table, Phase 2 increment 19.
-- Authored from prisma/schema.prisma in this increment, because the
-- Prisma engine download fails in this workspace and no local Prisma
-- run can generate it. This file is NOT claimed as generated by a
-- local Prisma run. Its proof is the GitHub Actions workflow in
-- .github/workflows/prisma-migration.yml, which runs prisma migrate
-- deploy with this file against an ephemeral Postgres 15 service
-- container, and which also runs prisma migrate diff from empty to
-- the schema as a cross check artifact. Do NOT run this migration
-- against any real database except through the manual Neon migrate
-- deploy workflow, .github/workflows/neon-migrate-deploy.yml, run
-- fresh by the owner on GitHub after this increment is pushed.
-- Table: HumanHelpRequest, one model from the schema. All ids are
-- UUIDs with gen_random_uuid defaults. All timestamps are
-- TIMESTAMP(3). Goal is study, work, or business, need is
-- consultation, review, or both, country is the country pack slug
-- as written. No reply time, price, or email is promised on a
-- request. Sample data: none.

CREATE TABLE "HumanHelpRequest" (
    "id" TEXT NOT NULL DEFAULT gen_random_uuid(),
    "name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "country" TEXT NOT NULL,
    "goal" TEXT NOT NULL,
    "need" TEXT NOT NULL,
    "message" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "HumanHelpRequest_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "HumanHelpRequest_createdAt_idx" ON "HumanHelpRequest"("createdAt");
CREATE INDEX "HumanHelpRequest_email_idx" ON "HumanHelpRequest"("email");
